%[text] # Table-Based Battery block
%[text] This script collects the open-circuit voltage and terminal voltage parameters of table-based battery block in a model file and makes the plots of the parameters.
% Model to collect parameter values.
mdl = "BatteryHV_SystemTable_refsub";
% Block path to the target battery block.
blkpath = "/Battery/Battery (Table-Based)";
%[text] Collect parameter values from the battery block in the model.
fullblkpath = mdl + blkpath;
BatteryHV_TestModelSetup
load_system(mdl)

% State of charge ... independent variable 1
SOC_normalized = eval(get_param(fullblkpath, "SOC_vec"))';
SOC_pct = SOC_normalized * 100;

% Battery temperature ... independent variable 2
T_vec = eval(get_param(fullblkpath, "T_vec"));
T_vec_unit = get_param(fullblkpath, "T_vec_unit");
TemperatureStr = "" + eval(get_param(fullblkpath, "T_vec")) + " " + T_vec_unit %[output:0d8db9e3]

% Open-circuit voltage, V0(SOC,T)
V0_mat = eval(get_param(fullblkpath, "V0_mat")) %[output:2adc897e]
V0_mat_unit = get_param(fullblkpath, "V0_mat_unit") %[output:4050057c]

% Terminal resistance, R0(SOC,T)
R0_mat = eval(get_param(fullblkpath, "R0_mat")) %[output:35100fda]
R0_mat_unit = get_param(fullblkpath, "R0_mat_unit") %[output:615c2430]
%[text] ## Open-ciruit voltage
fig = figure; %[output:8cbcac52]
fig.Position(3:4) = [600 400]; %[output:8cbcac52]
hold on %[output:8cbcac52]
grid on %[output:8cbcac52]
for idx = 1 : numel(T_vec)
  plot(SOC_pct, V0_mat(:,idx), LineWidth=2) %[output:8cbcac52]
end
set(gca, xdir = "reverse") %[output:8cbcac52]
legend(TemperatureStr, Location="southwest") %[output:8cbcac52]
xlabel("State of charge (%)") %[output:8cbcac52]
ylabel("(" + V0_mat_unit + ")") %[output:8cbcac52]
title("Open-circuit voltage, V0(SOC,T)") %[output:8cbcac52]
%[text] ## Terminal resistance
fig = figure; %[output:03230e5b]
fig.Position(3:4) = [600 400]; %[output:03230e5b]
hold on %[output:03230e5b]
grid on %[output:03230e5b]
for idx = 1 : numel(T_vec)
  plot(SOC_pct, R0_mat(:,idx), LineWidth=2) %[output:03230e5b]
end
set(gca, xdir = "reverse") %[output:03230e5b]
legend(TemperatureStr, Location="best") %[output:03230e5b]
xlabel("State of charge (%)") %[output:03230e5b]
ylabel("(" + R0_mat_unit + ")") %[output:03230e5b]
title("Terminal resistance, R0(SOC,T)") %[output:03230e5b]
